import{c as o,Q as t,j as a,m as i}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"OpenAI-Compatible Providers","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/openai-compatible.md","filePath":"configuration/openai-compatible.md","lastUpdated":null}'),r={name:"configuration/openai-compatible.md"};function n(s,e,p,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="openai-compatible-providers" tabindex="-1">OpenAI-Compatible Providers <a class="header-anchor" href="#openai-compatible-providers" aria-label="Permalink to &quot;OpenAI-Compatible Providers&quot;">​</a></h1><p>Use OpenAI or any gateway that speaks the OpenAI API.</p><h2 id="supported" tabindex="-1">Supported <a class="header-anchor" href="#supported" aria-label="Permalink to &quot;Supported&quot;">​</a></h2><ul><li>OpenAI (<code>api.openai.com</code>)</li><li>Azure OpenAI (deployment URL)</li><li>Self-hosted compatibles: vLLM, LocalAI, Together, custom proxies that expose <code>/v1/chat/completions</code></li></ul><p>FinSight’s <code>CompletionProvider</code> trait (<code>crates/finsight-providers</code>) abstracts the HTTP layer so the planner does not know which is behind it.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>In <strong>Settings → Agent</strong>, choose <strong>OpenAI-Compatible</strong>.</li><li>Fill base URL (e.g. <code>https://api.openai.com/v1</code>), model (e.g. <code>gpt-4o-mini</code>), and API key.</li><li>Save. The key is stored per-user inside your encrypted <code>data.sqlcipher</code> — not a global server slot.</li></ol><p>Auto-categorization uses the same provider and sends only the merchant + amount of uncategorized rows; the Copilot sends the question-scoped <code>FinancialContext</code>. See <a href="/FinSight/copilot/privacy">Privacy</a>.</p><h2 id="verifying" tabindex="-1">Verifying <a class="header-anchor" href="#verifying" aria-label="Permalink to &quot;Verifying&quot;">​</a></h2><p>Same as Ollama — ask the Copilot a grounded question and look for a cited total. On failure, the server logs show the HTTP status and the Copilot surface renders the provider error, not a silent miss.</p><p>See also: <a href="/FinSight/configuration/anthropic">Anthropic</a>, <a href="/FinSight/configuration/settings">Settings</a>.</p>',11)])])}const m=o(r,[["render",n]]);export{u as __pageData,m as default};
